const stories = [];

for (const story of $('When Executed by Another Workflow').first().json.REQUIRED_stories) {
  const storyItem = [];
  let buffer = "";
  const maxChunkLength = 30;

  for (const sentences of story.split('.')) {
    if (buffer.length >= maxChunkLength) {
      storyItem.push(buffer);
      buffer = "";
    }

    buffer += sentences;
  }

  if (buffer != "") {
    storyItem.push(buffer);
  }

  stories.push(storyItem);

}

return stories.map(chunks => ({
  json: {
    chunks
  }
}))

