const storiesMap = {};
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  const {
    story_id, generated_video_id, id
  } = item.json;
  if (!storiesMap[story_id]) {
    storiesMap[story_id] = []
  }
  storiesMap[story_id].push({generated_video_id, id})
}

let stories = Object.values(storiesMap);
for (const story of stories) {
  story.sort((a, b) => {
    if (a.id > b.id) {
      return 1;
    }
    if (a.id < b.id) {
      return -1;
    }
    return 0;
  })
}
stories = stories.map(story => story.map(item => item.generated_video_id))

return [{
  json: {
    stories
  }
}]

const stories = $input.first().json.stories;

const numbers = stories.map((_, index) => ({
  json: {
    narration: `Number ${index + 1}`,
    number: `${index + 1}` 
  }
}));

numbers.sort((a, b) => {
  const na = Number(a.json.number);
  const nb = Number(b.json.number);
  return nb - na;
});

return numbers;

