const chunks = [];

const storyIds = $('Insert story').all().map(story => story.json.id);
const stories = $('Split the stories to chunks').all().map((story, storyIndex) => {
  const chunks = [];
  for (const chunk of story.json.chunks) {
    chunks.push({
      chunk,
      videoId: $('Insert video').first().json.id,
      storyId: storyIds[storyIndex]
    })
  }
  return chunks;
}).flat()

return stories.map(story => ({
  json: story
}))

const stories = $('Prepare final data structure').first().json.stories;

for (const item of $input.all()) {
  item.json.data.forEach((el, index) => {
    stories[index].unshift(el.file_id);
  })
}

return [{
  json: {
    final_videos: [
      $('Video').first().json.video.intro_video_id,
      ...stories.flat(),
      $('Video').first().json.video.outro_video_id
    ].filter(Boolean)
  }
}]
